class Solution:
    def checktree(self, preorder, inorder, postorder, N):
        inorder_map = {v:i for i,v in enumerate(inorder)}
        self.preIndex = 0
        self.postIndex = 0

        def helper(start, end):
            if start > end:
                return True

            root = preorder[self.preIndex]
            idx = inorder_map[root]
            self.preIndex += 1

            if not helper(start, idx-1):
                return False
            if not helper(idx+1, end):
                return False

            if postorder[self.postIndex] != root:
                return False

            self.postIndex += 1
            return True

        return helper(0, N-1)
